using LocalGPT.BusinessObjects;

namespace LocalGPT.Interfaces;

/// <summary>Produces reviewed source from a language-specific CodeDOM provider; generation never executes source.</summary>
public interface ICodeDomSourceService
{
    /// <summary>Generates a C# class using the same CodeDOM semantics as reviewed code-generation artifacts.</summary>
    /// <param name="spec">Author-controlled source declaration.</param>
    /// <returns>Source text generated by the installed C# CodeDOM provider.</returns>
    string GenerateCSharpSource(CodeDomTypeSpec spec);

    /// <summary>Generates a standalone test entry point alongside the reviewed CodeDOM class.</summary>
    /// <param name="spec">Author-controlled source declaration.</param>
    /// <returns>Editable C# source. The caller must approve any sandbox execution separately.</returns>
    string GenerateCSharpSandboxProgram(CodeDomTypeSpec spec);
}
